    p = s.get('element_properties') or {}
    r = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    loads = [0.0] * n
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                overlap = min(max((r[i] + r[j]) / d - 1.0, 0.0), 3.0)
                loads[i] += occ[j] * overlap * overlap
    peak = 0.0
    for i in range(n):
        if occ[i] > 0:
            peak = max(peak, loads[i])
    return peak

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    props = [p.get(a.get('element')) or {} for a in sites]
    r = [a.get('covalent_radius_A') for a in props]
    en = [a.get('eneg') for a in props]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    weights = [0.0] * n
    totals = [0.0] * n
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8:
            if en[j] is not None and r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                w = occ[j] * max(1.5 - d / (r[i] + r[j]), 0.0) ** 2
                weights[i] += w
                totals[i] += w * en[j]
    total = 0.0
    scale = 0.0
    for i in range(n):
        a = props[i]
        g = a.get('group')
        row = a.get('row')
        v = a.get('valence_electrons')
        accepting = False
        if weights[i] > 1e-12 and en[i] is not None:
            accepting = en[i] > totals[i] / weights[i] + 0.4
        q = None
        if g == 1:
            q = -1.0 if row == 1 and accepting else 1.0
        elif g == 2:
            q = 2.0
        elif g == 13:
            q = -3.0 if accepting else 3.0
        elif g == 14:
            q = -4.0 if accepting or (en[i] is not None and en[i] >= 2.3) else 4.0
        elif g is not None and 15 <= g <= 17:
            q = float(g - 18)
        elif g == 18:
            q = 0.0
        elif v is not None and ((g is not None and 3 <= g <= 12) or (g is None and row is not None and row >= 6)):
            q = min(max(v, 0.0), 3.0)
        if q is not None:
            total += occ[i] * q
            scale += occ[i] * abs(q)
    return abs(total) / scale if scale > 0 else 0.0
